:root {
--radius-none: 0;
--radius-sm: 0.125rem;   /* 2px */
--radius-md: 0.25rem;    /* 4px — 기본 */
--radius-lg: 0.5rem;     /* 8px */
--radius-xl: 1rem;       /* 16px */
--radius-full: 9999px;
--shadow-none: none;
--shadow-sm: 0 2px 2px 0 rgba(0,0,0,0.10);                /* card */
--shadow-md: 0 2px 4px 0 rgba(0,0,0,0.15);                /* hover */
--shadow-lg: 0 2px 8px 0 rgba(0,0,0,0.20);                /* dropdown */
--shadow-xl: 0 16px 32px 0 rgba(0,0,0,0.25);              /* modal */
--duration-fast: 50ms;
--duration-base: 200ms;
--duration-slow: 400ms;
--ease-out: cubic-bezier(0, 0, 0.2, 1);
--ease-in-out: cubic-bezier(0.4, 0, 0.6, 1);
}
:root {
  /* Primary - Salesforce Blue */
  --color-primary-50:  #102E4A;
  --color-primary-100: #163F66;
  --color-primary-200: #20588A;
  --color-primary-300: #57A3FD;
  --color-primary-400: #2E84FB;
  --color-primary-500: #1B96FF;  /* SLDS brand 기본 */
  --color-primary-600: #0176D3;  /* hover */
  --color-primary-700: #014486;
  --color-primary-800: #032D60;
  --color-primary-900: #001639;

  /* Secondary - Sky/Cloud */
  --color-secondary-500: #0D9DDA;

  /* Neutral */
  --color-neutral-0:    #0F1114;
  --color-neutral-50:   #181B20;  /* dark background */
  --color-neutral-100:  #242830;
  --color-neutral-200:  #3E424A;  /* dark border */
  --color-neutral-300:  #5C616B;
  --color-neutral-500:  #8E939C;
  --color-neutral-700:  #C2C5CA;
  --color-neutral-800:  #DADDDF;
  --color-neutral-900:  #F3F3F3;
  --color-neutral-1000: #FFFFFF;

  /* Semantic */
  --color-success-bg: #173B28;
  --color-success-fg: #91DBA8;
  --color-warning-bg: #483A12;
  --color-warning-fg: #F9CF6B;
  --color-error-bg:   #4A2026;
  --color-error-fg:   #FF9EA8;
  --color-info-bg:    #102E4A;
  --color-info-fg:    #78BFFF;

  /* Surface */
  --bg-base:     #0F1114;        /* dark page */
  --bg-subtle:   #14171B;
  --bg-elevated: #181B20;        /* dark card */
  --bg-overlay:  #242830;

  /* Text */
  --text-primary:    #F3F3F3;
  --text-secondary:  #C2C5CA;
  --text-tertiary:   #A7ABB3;
  --text-on-primary: #FFFFFF;
  --text-disabled:   #6F747D;

  /* Border */
  --border-default: #3E424A;
  --border-subtle:  #2C3037;
  --border-strong:  #686D76;
  --border-focus:   #1B96FF;
}

